// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller == c.owner());
        uint256 codeSize;
        assembly {
            codeSize := extcodesize(c)
        }
        c.sudicideAnyone();
        uint256 codeSizeAfter;
        assembly {
            codeSizeAfter := extcodesize(c)
        }
        assertTrue(codeSizeAfter == codeSize);
    }
}
